#!/usr/bin/env python3
"""Pin complete K-02 generated bytes; keep this external gate distinct from Lean semantics."""
import argparse
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

sys.dont_write_bytecode = True
PIN = '1ac9422a12ab743a9bbb8b8ad508d37c582637df'
CONTRACT = 'kadmos.compiler.k02.v1'
OLD_PIN = 'fda8c6e42825b35afe5484a4af9d84d9d206ba9a'
# Reviewed compiler-output fingerprints, independent of the editable manifest.
EXPECTED = {
    'balance/world_checker.ts': '08aa10110b3a36450c2bd2552ac0bb89cc0f4216784f0f30df462abeef6b4e0a',
    'balance/ports.d.ts': 'debb1ab3db463e8691615a929b98ccf627c552820e2bf728203ec4cdf2d7cf80',
    'balance/world_checker.py': '50b4da8809d42e72bedc2287bf6fde09291988213e781f4fea173f8163f15437',
    'balance/ports.py': '56809a0466af05bf94a1a3968cf8d1f4de9a7c919acb0dfa0560b40b021447b3',
    'balance/admitted.json': '23e1e9a9a047a0497a6fe9ef35673d188fabb60e3833674ce3c5008ab320150d',
    'order_phase/world_checker.ts': '161631c389776c7fee161d4a6a8d7037147c435a66f650125649e7d5c400b402',
    'order_phase/ports.d.ts': 'a60a83d94e37d7ecacefe99e5a2152034de0eeaf33e31340cf9f7993fe5b0cbf',
    'order_phase/world_checker.py': 'f3dc44d14365e9349b1dc5d13f9d9935e7d7a9aeb84a49ed211453b241e82da0',
    'order_phase/ports.py': 'da9cab2af85c26fa460d93b446e71b71d82e3951fb3782d5c2474a160dcbf830',
    'order_phase/admitted.json': 'a70d58c266b1b225d01db73f01a8b507b8edc7149b6e6c72ef56377982c921fa',
}
FIXTURE_SHA = '3006d2ece39affff067b4116fe16a3aeb61cff4fd9ba0dac2fba43fd574382c3'
YAML_SHA = {'balance': '1357baa55f5cc0453a491df264ca75adacad1db580e4bc952dc4adffc900258b',
            'order_phase': '53bd1b2a133ff562c01a9b7b10066ed7f78fc45c10a1a821390de6164038db60'}


class ArtifactError(ValueError):
    pass


def sha(data):
    return hashlib.sha256(data).hexdigest()


def ordered_json(data):
    def pairs(xs):
        out = {}
        for key, value in xs:
            if key in out:
                raise ArtifactError(f'duplicate JSON key: {key}')
            out[key] = value
        return out
    return json.loads(data, object_pairs_hook=pairs)


def extract_json_literals(ts, py):
    def source_string(pattern, source):
        match = re.search(pattern, source)
        if not match:
            raise ArtifactError('missing emitted JSON source literal')
        # JSON string syntax emitted by Kadmos in both target languages.
        return json.loads(match.group(1))
    world_ts = source_string(r'const world: WorldData = JSON\.parse\(("(?:\\.|[^"\\])*")\);', ts)
    defaults_ts = source_string(r'const contextDefaults:[^\n]*= JSON\.parse\(("(?:\\.|[^"\\])*")\);', ts)
    world_py = source_string(r'_WORLD = _freeze\(json\.loads\(("(?:\\.|[^"\\])*")\)\)', py)
    return ordered_json(world_ts), ordered_json(world_py), ordered_json(defaults_ts)


def check_artifacts(root):
    root = Path(root).resolve()
    base = root / 'conformance/kadmos-generated-k02'
    manifest = ordered_json((base / 'provenance.json').read_bytes())
    if manifest['kadmosCommit'] != PIN or manifest['compilerContract'] != CONTRACT or manifest['oldBridgePin'] != OLD_PIN:
        raise ArtifactError('compiler/bridge provenance mismatch')
    if manifest['files'] != EXPECTED or manifest['yamlSha256'] != YAML_SHA or manifest['fixturesLeanSha256'] != FIXTURE_SHA:
        raise ArtifactError('reviewed manifest mismatch')
    found = {str(p.relative_to(base)) for p in base.glob('*/*') if p.is_file()}
    if found != set(EXPECTED):
        raise ArtifactError(f'generated file inventory mismatch: {found ^ set(EXPECTED)}')
    for path, expected in EXPECTED.items():
        if sha((base / path).read_bytes()) != expected:
            raise ArtifactError(f'generated byte mismatch: {path}')
    for name in ('balance', 'order_phase'):
        yaml = root / 'conformance/kadmos-ir-bridge' / f'{name}.world.yaml'
        if sha(yaml.read_bytes()) != YAML_SHA[name]:
            raise ArtifactError(f'YAML drift: {name}')
    old = ordered_json((root / 'conformance/kadmos-ir-bridge/parsed.json').read_bytes())
    for name in ('balance', 'order_phase'):
        admitted = ordered_json((base / name / 'admitted.json').read_bytes())
        canonical = lambda x: json.dumps(x, ensure_ascii=False, separators=(',', ':'))
        if canonical(admitted) != canonical(old[name]):
            raise ArtifactError(f'T-395 admitted fixture mismatch: {name}')
        ts = (base / name / 'world_checker.ts').read_text()
        py = (base / name / 'world_checker.py').read_text()
        ts_world, py_world, defaults = extract_json_literals(ts, py)
        if canonical(ts_world) != canonical(admitted) or canonical(py_world) != canonical(admitted):
            raise ArtifactError(f'embedded emitted world mismatch: {name}')
        expected_defaults = {k: v.get('default', 0) for k, v in admitted['context'].items()}
        if defaults != expected_defaults:
            raise ArtifactError(f'embedded emitted defaults mismatch: {name}')
    fixture = root / 'Harmonia/Applications/Kadmos/Generated/Fixtures.lean'
    if sha(fixture.read_bytes()) != FIXTURE_SHA:
        raise ArtifactError('complete Lean source literals mismatch')
    return {'files': len(EXPECTED), 'fixturesLeanSha256': FIXTURE_SHA}


if __name__ == '__main__':
    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument('--root', type=Path, default=Path(__file__).resolve().parents[1])
    cli.add_argument('--self-test', action='store_true')
    cli.add_argument('--kadmos', type=Path)
    args = cli.parse_args()
    if args.self_test:
        from test_kadmos_generated_k02_artifacts import K02Artifacts
        import unittest
        sys.exit(0 if unittest.TextTestRunner(verbosity=2).run(
            unittest.defaultTestLoader.loadTestsFromTestCase(K02Artifacts)).wasSuccessful() else 1)
    try:
        result = check_artifacts(args.root)
        if args.kadmos:
            export = Path(__file__).resolve().parents[1] / 'tools/export_kadmos_generated_k02.mjs'
            import tempfile
            with tempfile.TemporaryDirectory(prefix='t398-k02-check-') as tmp:
                subprocess.run(['node', str(export), '--kadmos', str(args.kadmos),
                                '--out', tmp, '--check'], check=True)
        print('K-02 ARTIFACT PASS:', result)
    except (ArtifactError, subprocess.CalledProcessError) as exc:
        print('K-02 ARTIFACT REJECTED:', exc, file=sys.stderr)
        sys.exit(1)
